<?php
if(!defined('ABSPATH'))exit;$post_id=get_queried_object_id();if(!$post_id)return;$author_id=(int)get_post_field('post_author',$post_id);if(!$author_id)return;$u=get_userdata($author_id);if(!$u)return;$role=get_user_meta($author_id,'techpress_role',true)?:__('Contributor','digipublish-core');$bio=get_the_author_meta('description',$author_id);echo '<section class="tp-post-author-card"><div class="tp-post-author-card__avatar">'.get_avatar($author_id,92).'</div><div><h3>'.esc_html($u->display_name).'</h3><p class="tp-post-author-card__role">'.esc_html($role).'</p>';if($bio)echo '<p class="tp-post-author-card__bio">'.esc_html(wp_trim_words($bio,60)).'</p>';echo '<a class="tp-post-author-card__link" href="'.esc_url(get_author_posts_url($author_id)).'">'.esc_html(sprintf(__('All Stories by %s','digipublish-core'),$u->display_name)).' →</a></div></section>';
